addEventListener("resize", place);
const g = fx.getContext("2d"), COL = ["rgba(150,205,255,.95)", "rgba(185,125,255,.95)", "rgba(22,216,255,.95)"];
let W = 0, H = 0, P = null, raf = 0, t0 = 0, stopAt = 0, lastT = 0, timers = [];
function size() { const d = Math.min(devicePixelRatio || 1, 2); W = innerWidth; H = innerHeight; fx.width = W * d; fx.height = H * d; g.setTransform(d, 0, 0, d, 0, 0); g.fillStyle = "#05040a"; g.fillRect(0, 0, W, H); }
function samp(draw) {
const o = document.createElement("canvas"); o.width = W; o.height = H; const c = o.getContext("2d"); draw(c);
const d = c.getImageData(0, 0, W, H).data, a = [];
for (let y = 0; y < H; y += 3) for (let x = 0; x < W; x += 3) if (d[(y * W + x) * 4 + 3] > 128) a.push([x, y]);
return a;
}
const word = t => samp(c => { c.fillStyle = "#fff"; c.textAlign = "center"; c.textBaseline = "middle"; const fs = Math.min(W * .9 / Math.max(t.length * .6, 3), H * .34, 300); c.font = "600 " + fs + "px Oswald,Impact,'Arial Narrow',sans-serif"; c.fillText(t, W / 2, H * .46); });
const bust = () => samp(c => { const x = W > 760 ? W * .64 : W * .5, r = Math.min(H * .12, W * .2); c.fillStyle = "#fff"; c.beginPath(); c.ellipse(x, H * .34, r * .82, r * 1.1, .1, 0, 7); c.fill(); c.fillRect(x - r * .3, H * .4, r * .6, H * .12); c.beginPath(); c.ellipse(x, H * .88, Math.min(W * .3, H * .38), H * .3, 0, 0, 7); c.fill(); });
const rects = list => samp(c => { c.strokeStyle = "#fff"; c.lineWidth = 5; list.forEach(r => c.strokeRect(W * r[0], H * r[1], W * r[2], H * r[3])); });
const cards = () => rects([[.08, .26, .24, .14], [.11, .44, .24, .14], [.08, .62, .24, .14]]);
const frames = () => rects([[.2, .2, .26, .3], [.5, .28, .28, .32], [.36, .6, .17, .2], [.68, .1, .14, .14]]);
function column() {
const x = W / 2, gy = H * .6;
P.forEach((p, i) => { if (i % 3) { p.col = 1; p.tx = x + (Math.random() - .5) * Math.min(70, W * .12) * Math.random(); p.ty = Math.random() * gy; p.v = 1.5 + Math.random() * 3; } else { p.col = 0; const t = Math.pow(Math.random(), 1.5); p.tx = x + (Math.random() - .5) * W * 1.5 * t; p.ty = gy + t * (H - gy); } });
}
function formation(key, a) {
if (/^(contact|findme|brief)$/.test(key)) return column();
const pts = key === "home" ? word("TIAMO") : key === "about" ? bust().concat(cards()) : /^(services|process)$/.test(key) ? cards().concat(word(label(a)).filter((_, i) => i % 3 === 0)) : /^(work|cinema|creation|beforeafter)$/.test(key) ? frames() : word(label(a));
for (let i = pts.length - 1; i > 0; i--) { const j = Math.random() * (i + 1) | 0; [pts[i], pts[j]] = [pts[j], pts[i]]; }
P.forEach((p, i) => { const q = pts[i % pts.length]; p.tx = q[0] + (Math.random() - .5) * 2; p.ty = q[1] + (Math.random() - .5) * 2; p.col = 0; });
}
function loop(t) {
const el = t - t0, dt = Math.min(t - (lastT || t - 16), 120) / 1000; lastT = t; g.fillStyle = "rgba(5,4,10," + Math.min(.5, .2 * dt * 60) + ")"; g.fillRect(0, 0, W, H);
for (const p of P) {
if (p.col) { p.ty += p.v * dt * 60; if (p.ty > H * .6) { p.ty = 0; p.y = 0; } }
const k = el > p.d ? 1 - Math.exp(-dt * (3 + p.sp * 4)) : 0, ox = p.x, oy = p.y;
p.x += (p.tx - p.x) * k + Math.sin(t * .0012 + p.ph) * .12; p.y += (p.ty - p.y) * k + Math.cos(t * .001 + p.ph) * .12;
g.strokeStyle = p.c; g.lineWidth = p.r; g.beginPath(); g.moveTo(ox, oy); g.lineTo(p.x + .01, p.y); g.stroke();
}
raf = performance.now() < stopAt ? requestAnimationFrame(loop) : 0;
}
function travel(a) {
if (RM || !a) { a && a.click(); return; }
timers.forEach(clearTimeout); timers = [];
if (!fx.classList.contains("on") || fx.width !== Math.round(innerWidth * Math.min(devicePixelRatio || 1, 2))) size();
if (!P) P = Array.from({ length: innerWidth < 1100 ? 1200 : 1900 }, (_, i) => ({ x: W / 2, y: H * .45, tx: 0, ty: 0, d: 0, sp: Math.random(), ph: Math.random() * 6, r: .7 + Math.random() * 1.1, c: COL[i % 3], col: 0, v: 0 }));
const key = a.getAttribute("href").slice(1);
t0 = performance.now(); lastT = 0; P.forEach(p => p.d = Math.random() * 380); formation(key, a);
cap.textContent = two(links.indexOf(a)) + "  /  " + two(links.length - 1) + "   —   " + label(a); cap.classList.remove("show"); fx.classList.add("on");
stopAt = t0 + 2500; if (!raf) raf = requestAnimationFrame(loop);
timers.push(setTimeout(() => a.click(), 480), setTimeout(() => cap.classList.add("show"), 650), setTimeout(() => { fx.classList.remove("on"); cap.classList.remove("show"); }, 1800));
}
let ct = 0, panelOpen = false, open = false;
const setPanel = v => { panelOpen = v; panel.classList.toggle("is-open", v); more.classList.toggle("is-open", v); more.setAttribute("aria-expanded", v); };
const setOpen = v => { open = v; dock.classList.toggle("is-open", v); rest.setAttribute("aria-expanded", v); setTimeout(place, 650); };
function closeAll() { clearTimeout(ct); setPanel(false); if (open) setOpen(false); }
const disarm = () => { clearTimeout(ct); ct = setTimeout(() => { if (!dock.matches(":hover") && !dock.matches(":focus-within")) closeAll(); }, 320); };
more.addEventListener("click", () => setPanel(!panelOpen));
more.addEventListener("pointerenter", e => { if (e.pointerType !== "touch") { clearTimeout(ct); setPanel(true); } });
rest.addEventListener("click", () => setOpen(!open));
const hz = document.querySelector(".header-actions");
let lockUntil = 0;
if (hz) { hz.addEventListener("pointerenter", () => { lockUntil = performance.now() + 600; closeAll(); }); hz.addEventListener("click", () => { lockUntil = performance.now() + 1400; closeAll(); }); }
dock.addEventListener("pointerenter", e => { if (e.pointerType === "touch" || performance.now() < lockUntil) return; clearTimeout(ct); if (getComputedStyle(rest).display !== "none") setOpen(true); });
dock.addEventListener("pointerleave", e => { if (e.pointerType !== "touch") disarm(); });
dock.addEventListener("focusin", () => { if (performance.now() >= lockUntil && getComputedStyle(rest).display !== "none") setOpen(true); });
